import org.owasp.esapi.util.CollectionsUtil;

public class PercentCodec extends Codec {

    private static final String ALPHA_NUMERIC_STR =
            "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final String RFC3986_NON_ALPHANUMERIC_UNRESERVED_STR = "-._~";
    private static final boolean ENCODED_NON_ALPHA_NUMERIC_UNRESERVED = true;
    private static final String UNENCODED_STR = ALPHA_NUMERIC_STR
            + (ENCODED_NON_ALPHA_NUMERIC_UNRESERVED ? "" : RFC3986_NON_ALPHANUMERIC_UNRESERVED_STR);
    private static final Set<Character> UNENCODED_SET =
            CollectionsUtil.strToUnmodifiableSet(UNENCODED_STR);

    /* Hexadecimal digit lookup table – immutable and thread‑safe */
    private static final char[] HEX_DIGITS = "0123456789ABCDEF".toCharArray();

    // --------------------------------------------------------------------
    // Public API
    // --------------------------------------------------------------------

    /**
     * Encode a character for URLs.
     *
     * @param immune characters not to encode (may be {@code null})
     * @param c      character to encode (must not be {@code null})
     * @return the encoded string representing {@code c}
     */
    public String encodeCharacter(char[] immune, Character c) {
        // Defensive programming – fail fast on null input
        Objects.requireNonNull(c, "Character to encode cannot be null");

        final String cStr = String.valueOf(c);

        // Honor the caller supplied immunity list
        if (immune != null) {
            for (char ic : immune) {
                if (ic == c) {
                    return cStr;
                }
            }
        }

        // Characters that are safe per RFC 3986 do not need encoding
        if (UNENCODED_SET.contains(c)) {
            return cStr;
        }

        // Convert to UTF‑8 bytes and percent‑encode each byte
        final byte[] bytes = toUtf8Bytes(cStr);
        final StringBuilder sb = new StringBuilder(bytes.length * 3);
        for (byte b : bytes) {
            appendTwoUpperHex(sb.append('%'), b);
        }
        return sb.toString();
    }

    // --------------------------------------------------------------------
    // Private helpers
    // --------------------------------------------------------------------

    /**
     * Append two hexadecimal digits (uppercase) to the supplied {@link StringBuilder}.
     *
     * @param sb the builder to append to
     * @param b  the byte value to encode
     * @return the same {@link StringBuilder} instance for chaining
     */
    private static StringBuilder appendTwoUpperHex(StringBuilder sb, int b) {
        final int unsigned = b & 0xFF;
        sb.append(HEX_DIGITS[unsigned >>> 4]);   // high nibble
        sb.append(HEX_DIGITS[unsigned & 0x0F]);   // low nibble
        return sb;
    }

    /**
     * Convert a string to its UTF‑8 byte representation.
     *
     * @param str the string to convert
     * @return a byte array containing the UTF‑8 encoding of {@code str}
     */
    private static byte[] toUtf8Bytes(String str) {
        return str.getBytes(StandardCharsets.UTF_8);
    }

