import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a name derived from {@code name}.
     * The method sanitises the supplied name to prevent directory‑traversal attacks,
     * ensures the resulting file resides within {@code dir}, and guarantees a unique
     * filename by appending a numeric suffix if needed.
     *
     * @param dir  the target directory where the file will be created; must not be {@code null}
     * @param name the desired filename; may contain query parameters or path components
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the sanitized name is empty
     * @throws SecurityException        if the resolved file would be outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("Name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Remove any path components – keep only the base name
        name = new File(name).getName();

        // Reject empty or invalid names
        if (name.isEmpty()) {
            throw new IllegalArgumentException("Name must not be empty after sanitisation");
        }

        // Normalise the directory and target paths
        File dirCanonical;
        File targetCanonical;
        try {
            dirCanonical = dir.getCanonicalFile();
            File tentative = new File(dirCanonical, name);
            targetCanonical = tentative.getCanonicalFile();
        } catch (IOException e) {
            throw new RuntimeException("Failed to resolve canonical paths", e);
        }

        // Ensure the target is inside the intended directory
        String dirPath = dirCanonical.getPath();
        String targetPath = targetCanonical.getPath();
        if (!targetPath.startsWith(dirPath + File.separator)) {
            throw new SecurityException(
                    "Attempted directory traversal: " + name + " resolves outside " + dirPath);
        }

        // Resolve name collisions by appending a numeric suffix
        String prefix;
        String suffix;
        int dot = name.lastIndexOf('.');
        if (dot < 0) {
            prefix = name;
            suffix = "";
        } else {
            prefix = name.substring(0, dot);
            suffix = name.substring(dot);
        }

        File file = new File(dirCanonical, name);
        int index = 2;
        while (file.exists()) {
            file = new File(dirCanonical, prefix + "-" + index++ + suffix);
        }

        // Create parent directories if they do not exist
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods

}
