import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // other methods

    /**
     * Validates a media type token (major or subtype).
     *
     * <p>The method uses a strict whitelist based on RFC 7230 § 3.2.6
     * (token definition). It allows alphanumeric characters and the
     * following punctuation: ! # $ % & ' * + - . ^ _ ` | ~.
     * The wildcard character '*' is also accepted as a special case.</p>
     *
     * @param str the token to validate
     * @return {@code true} if the token is valid, {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the wildcard token used in media types
        if ("*".equals(str)) {
            return true;
        }
        // RFC 7230 token characters
        // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
        //        "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
        // Note: '*' is already handled above, so it is omitted from the regex.
        final Pattern TOKEN_PATTERN = Pattern.compile(
                "^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // other methods
}
