        String destination = samlResponse.getDestination();
        if (destination == null || !destination.equals(assertionConsumerURL)) {
            LOG.fine("The Response must contain a destination that matches the assertion consumer URL");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE,
                    "invalidSAMLsecurity");
        }

        /* ------------------------------------------------------------------
         * Assertion level checks
         * ------------------------------------------------------------------ */
        // Ensure each assertion has a unique ID and that signatures cover the assertion
        checkUniqueAssertionIds(assertions);

        boolean foundValidSubject = false;
        Date sessionNotOnOrAfter = null;

        for (Assertion assertion : assertions) {
            // Validate the assertion issuer
            if (assertion.getIssuer() == null) {
                LOG.fine("Assertion Issuer must not be null");
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE,
                        "invalidSAMLsecurity");
            }
            validateIssuer(assertion.getIssuer());

