            final ParameterizedJobMixIn.ParameterizedJob project =
                    (ParameterizedJobMixIn.ParameterizedJob) item;

            listener.getLogger().println("Scheduling project: "
                    + ModelHyperlinkNote.encodeTo(project));

            node.addAction(new LabelAction(
                    Messages.BuildTriggerStepExecution_building_(project.getFullDisplayName())));

            List<Action> actions = new ArrayList<>();

            if (step.getWait()) {
                StepContext context = getContext();
                actions.add(new BuildTriggerAction(context, step.isPropagate()));
                // Log only the project name and a generic context identifier
