    /**
     * Normalizes a URI path by ensuring it has exactly one leading slash
     * and removing any additional leading slashes. If the input is {@code null},
     * {@code null} is returned. An empty path is treated as {@code "/"}.
     *
     * @param path the original path string
     * @return the normalized path
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Count leading slashes
        int leading = 0;
        while (leading < path.length() && path.charAt(leading) == '/') {
            leading++;
        }

        // Extract the rest of the path after the leading slashes
        String rest = path.substring(leading);

        // Build the normalized path: one leading slash + rest
        String normalized = "/" + rest;

        // Handle the special case where the original path was empty or consisted solely of slashes
        // In that case, rest will be empty and normalized will correctly be "/"
        return normalized;
    }

