class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from {@code in} into {@code out} using a simple
     * run‑length encoding scheme. The method validates the input stream
     * to guard against malformed data and to prevent infinite loops or
     * excessive memory usage that could lead to a denial‑of‑service
     * condition.
     *
     * @param in  the source input stream
     * @param out the destination buffer
     * @throws IOException if the stream ends unexpectedly or the
     *                     compressed data would overflow {@code out}
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();          // read the control byte
            if (n == -1) {
                throw new IOException("Unexpected end of stream while reading control byte");
            }

            if (n > 128) {              // repeat the following byte
                int value = in.read();  // byte to repeat
                if (value == -1) {
                    throw new IOException("Unexpected end of stream while reading repeat value");
                }

                int repeatCount = n & 0x7F;   // number of repetitions
                if (repeatCount == 0) {
                    continue;                 // nothing to write
                }

                if (position + repeatCount > total) {
                    throw new IOException("Compressed data exceeds expected output size");
                }

                byte repeatedByte = (byte) value;
                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = repeatedByte;
                }
            } else {                    // literal copy of the next n bytes
                int literalCount = n;
                if (literalCount == 0) {
                    continue;                 // nothing to copy
                }

                if (position + literalCount > total) {
                    throw new IOException("Compressed data exceeds expected output size");
                }

                for (int i = 0; i < literalCount; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new IOException("Unexpected end of stream while reading literal data");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

