public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /* Regular expression that matches a minimal ISO‑639 language tag
       optionally followed by an underscore and a two‑letter country code.
       This prevents arbitrary characters that could be used for XSS. */
