     * be already a Locale or a String. The input is validated against
     * a whitelist of supported locales to prevent XSS or malformed
     * locale values.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;
        if (requestedLocale != null) {
            if (requestedLocale instanceof Locale) {
                locale = (Locale) requestedLocale;
            } else {
                String localeStr = requestedLocale.toString().trim();

                // Basic syntax validation
                Matcher m = LOCALE_PATTERN.matcher(localeStr);
                if (!m.matches()) {
                    LOG.warn("Received locale string does not match expected pattern: {}", localeStr);
                } else {
                    // Convert to Locale and verify it is supported
                    Locale candidate = LocalizedTextUtil.localeFromString(localeStr, null);
                    if (candidate != null && isSupportedLocale(candidate)) {
                        locale = candidate;
                    } else {
                        LOG.warn("Locale '{}' is not supported by the JVM", localeStr);
                    }
                }
            }

            if (locale != null) {
                LOG.debug("Applied request locale: {}", locale);
            }
        }
        return locale;
    }

    /**
     * Checks whether the supplied Locale is one of the locales
     * returned by {@link Locale#getAvailableLocales()}.
     *
     * @param locale the Locale to check
     * @return true if the locale is supported, false otherwise
     */
    private boolean isSupportedLocale(Locale locale) {
        Locale[] available = Locale.getAvailableLocales();
        for (Locale availableLocale : available) {
            if (availableLocale.equals(locale)) {
                return true;
            }
        }
        return false;
    }

    // other methods

}
