     * <p>
     * If the name matches the allowed pattern it is returned unchanged.
     * Otherwise a warning is logged and a safe default action name is returned.
     *
     * @param rawActionName action name extracted from URI
     * @return a sanitized action name
     */
    protected String cleanupActionName(final String rawActionName) {
        if (rawActionName == null || rawActionName.isEmpty()) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null or empty action name, using default action [{}].", DEFAULT_SAFE_ACTION);
            }
            return DEFAULT_SAFE_ACTION;
        }

        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        } else {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Action/method [{}] does not match allowed action names pattern [{}], using default action [{}].",
                        rawActionName, allowedActionNames.pattern(), DEFAULT_SAFE_ACTION);
            }
            return DEFAULT_SAFE_ACTION;
        }
    }

    // other methods

}
