    /**
     * Safely extracts entries from an archive into {@code targetDirectory}.
     *
     * <p>This implementation mitigates path‑traversal attacks by:
     * <ul>
     *   <li>Normalizing the target directory path once using {@link Path#toRealPath()}.</li>
     *   <li>Rejecting entry names that are absolute or contain suspicious components
     *       such as {@code ..} or leading separators.</li>
     *   <li>Resolving each entry name against the target directory and normalizing
     *       the result before any file operations.</li>
     *   <li>Verifying that the resolved path is still within the target directory
     *       using {@link Path#startsWith(Path)}.</li>
     * </ul>
     *
     * @param supplier      provides archive entries
     * @param writer        writes entry data to an output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if extraction fails or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical target directory once
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has empty name");
            }
            if (entryName.contains("\0")) { // null byte injection
                throw new IOException("archive entry contains null byte: " + entryName);
            }
            // Reject absolute paths or paths starting with a separator
            if (Path.of(entryName).isAbsolute()
                    || entryName.startsWith("/") || entryName.startsWith("\\")
                    || entryName.startsWith("./") || entryName.startsWith(".\\")) {
                throw new IOException("archive entry has disallowed absolute or relative prefix: "
                        + entryName);
            }

            // Resolve and normalize the path
            Path resolvedPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still under the target directory
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName
                        + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create directory if it does not exist
                if (!Files.isDirectory(resolvedPath)) {
                    Files.createDirectories(resolvedPath);
                }
            } else {
                // Ensure parent directories exist
                Path parent = resolvedPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write file contents
                try (OutputStream out = Files.newOutputStream(
                        resolvedPath,
                        StandardOpenOption.CREATE_NEW,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

