import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // other methods

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while protecting
     * against XML External Entity (XXE) attacks. The method explicitly disables
     * external entity resolution and DTD processing on both the {@link SAXParserFactory}
     * and the underlying {@link XMLReader}. If a custom {@link SAXParserFactory}
     * is supplied via the Camel {@link Exchange}, the same security features are
     * applied to it.
     *
     * @param source   the input stream source
     * @param exchange optional Camel exchange that may contain a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the parser cannot be created
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Prefer a factory supplied by the exchange, otherwise create a new one
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            try {
                sfactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            } catch (Exception e) {
                LOG.warn("SAXParserFactory does not support FEATURE_SECURE_PROCESSING: {}", e.toString());
            }

            // Explicitly disable external entity resolution and DTD processing
            try {
                sfactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
                sfactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
                sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            } catch (Exception e) {
                LOG.warn("Failed to set XXE protection features on SAXParserFactory: {}", e.toString());
            }

            sfactory.setNamespaceAware(true);
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Disable DOCTYPE declarations on the XMLReader
            try {
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.warn("XMLReader does not support disallow-doctype-decl feature: {}", e.toString());
            }

        } catch (Exception ex) {
            LOG.error("Cannot create a secure SAXParser/XMLReader: {}", ex.toString(), ex);
            throw new SAXException("Failed to create a secure SAXParser", ex);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    // other methods
}
